"""Entry point: builds every generated file in memory."""

from __future__ import annotations

from pathlib import Path

from . import model, php, spec, tests_gen

GENERATED_DIRS = ("src/Resources", "src/Types", "tests/Generated")
GENERATED_FILES = ("src/DiditClient.php", "src/Params.php")
MARKER = "Code generated by codegen from openapi/*.json. DO NOT EDIT."


def build(root: Path) -> tuple[dict[str, str], list[str]]:
    s = spec.load(root)
    reg = model.Registry()
    ops = model.build(reg, s.server_operations)
    _check_names(reg)
    out = php.Output()

    tree = php.resource_tree(ops)
    out.add("src/DiditClient.php", php.emit_client(tree))
    for node in php.walk(tree):
        rel = node.fqcn.removeprefix("Didit\\").replace("\\", "/")
        out.add(f"src/{rel}.php", php.emit_resource(node))

    for m in sorted(reg.models.values(), key=lambda x: x.name):
        out.add(f"src/Types/{m.name}.php", php.emit_model(m))
    for e in sorted(reg.enums.values(), key=lambda x: x.name):
        out.add(f"src/Types/{e.name}.php", php.emit_enum(e))

    op_aliases = []
    component_shapes = {}
    for om in ops:
        if om.body_alias is None:
            continue
        if om.body is not None and om.body_alias == om.body.name:
            continue
        op_aliases.append((om.body_alias, php.op_alias_fields(om)))
    alias_names = {a for a, _ in op_aliases}
    for shape in reg.shapes.values():
        if shape.name in alias_names:
            continue  # the op-level alias (body + query + headers) replaces the body-only shape
        component_shapes[shape.name] = shape
    out.add("src/Params.php", php.emit_params(list(component_shapes.values()), op_aliases))

    for path, content in tests_gen.emit(ops, tree).items():
        out.add(path, content)
    return out.files, reg.notes


def _check_names(reg: model.Registry) -> None:
    reserved = {"File", "Version", "Params", "DiditClient", "RequestOptions"}
    clash = sorted(n for n in reg.shapes if n in reserved)
    if clash:
        raise spec.SpecError(f"request shape names clash with core classes in namespace Didit: {clash}")


def existing_generated(root: Path) -> set[str]:
    found: set[str] = set()
    for d in GENERATED_DIRS:
        base = root / d
        if base.exists():
            for p in base.rglob("*.php"):
                found.add(p.relative_to(root).as_posix())
    for f in GENERATED_FILES:
        if (root / f).exists():
            found.add(f)
    return found
